import { useRef } from "react";
import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";

interface TiltCardProps {
  intensity?: number;
  glow?: string;
  radius?: number;
}

export default function TiltCard({
  intensity = 1,
  glow = "#0071e3",
  radius = 16,
}: TiltCardProps) {
  const ref = useRef<HTMLDivElement>(null);
  const mx = useMotionValue(0);
  const my = useMotionValue(0);
  const rx = useSpring(
    useTransform(my, [-0.5, 0.5], [12 * intensity, -12 * intensity]),
    { stiffness: 220, damping: 20 },
  );
  const ry = useSpring(
    useTransform(mx, [-0.5, 0.5], [-12 * intensity, 12 * intensity]),
    { stiffness: 220, damping: 20 },
  );

  return (
    <div style={{ perspective: 900 }}>
      <motion.div
        ref={ref}
        style={{
          rotateX: rx,
          rotateY: ry,
          borderRadius: radius,
          boxShadow: `0 20px 60px -20px ${glow}66`,
        }}
        className="w-64 border border-black/10 bg-white p-6 text-[#1d1d1f] dark:border-white/10 dark:bg-[#1c1c1e] dark:text-[#f5f5f7]"
        onMouseMove={(e) => {
          const el = ref.current;
          if (!el) return;
          const r = el.getBoundingClientRect();
          mx.set((e.clientX - r.left) / r.width - 0.5);
          my.set((e.clientY - r.top) / r.height - 0.5);
        }}
        onMouseLeave={() => {
          mx.set(0);
          my.set(0);
        }}
      >
        <div className="mb-4 h-10 w-10 rounded-full" style={{ backgroundColor: glow }} />
        <h3 className="text-base font-semibold">Tilt 3D</h3>
        <p className="mt-1.5 text-sm text-[#86868b]">
          Mueve el cursor sobre la tarjeta para inclinarla en el espacio.
        </p>
      </motion.div>
    </div>
  );
}

import { useRef, useState } from "react";

interface GlowCardProps {
  intensity?: number;
  glow?: string;
  radius?: number;
}

export default function GlowCard({
  intensity = 1,
  glow = "#6366f1",
  radius = 16,
}: GlowCardProps) {
  const [pos, setPos] = useState({ x: 50, y: 50 });
  const [hover, setHover] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  return (
    <div
      ref={ref}
      className="relative w-64 overflow-hidden border border-black/10 bg-white p-6 text-[#1d1d1f] dark:border-white/10 dark:bg-[#1c1c1e] dark:text-[#f5f5f7]"
      style={{ borderRadius: radius }}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      onMouseMove={(e) => {
        const el = ref.current;
        if (!el) return;
        const r = el.getBoundingClientRect();
        setPos({
          x: ((e.clientX - r.left) / r.width) * 100,
          y: ((e.clientY - r.top) / r.height) * 100,
        });
      }}
    >
      <div
        className="pointer-events-none absolute inset-0 transition-opacity duration-300"
        style={{
          opacity: hover ? Math.min(1, intensity * 0.6) : 0,
          background: `radial-gradient(320px circle at ${pos.x}% ${pos.y}%, ${glow}55, transparent 70%)`,
        }}
      />
      <div className="relative">
        <div className="mb-4 h-10 w-10 rounded-full" style={{ backgroundColor: glow }} />
        <h3 className="text-base font-semibold">Spotlight</h3>
        <p className="mt-1.5 text-sm text-[#86868b]">
          Un brillo radial sigue al cursor por la superficie de la tarjeta.
        </p>
      </div>
    </div>
  );
}

import { motion } from "framer-motion";
import { CalendarDays, CloudSun } from "lucide-react";

interface WeatherWidgetProps {
  temp?: number;
  city?: string;
  eventDate?: string;
  eventTitle?: string;
}

export default function WeatherWidget({
  temp = 23,
  city = "Madrid",
  eventDate = "Viernes, 25",
  eventTitle = "Cena · 20:30",
}: WeatherWidgetProps) {
  return (
    <motion.div
      whileHover={{ scale: 1.02 }}
      transition={{ type: "spring", stiffness: 300, damping: 30 }}
      className="w-64 rounded-[28px] bg-white/70 p-5 text-[#1d1d1f] shadow-[0_1px_2px_rgba(0,0,0,0.03),0_8px_28px_rgba(0,0,0,0.05)] backdrop-blur-[20px] dark:bg-black/70 dark:text-[#f5f5f7]"
    >
      <div className="flex justify-between">
        <div>
          <p className="text-xs text-[#86868b]">{city}</p>
          <strong className="text-4xl font-medium">{temp}°</strong>
        </div>
        <CloudSun className="h-10 w-10 text-[#0071e3]" />
      </div>
      <div className="my-4 h-px bg-black/10 dark:bg-white/10" />
      <div className="flex items-center gap-3">
        <CalendarDays className="h-8 w-8 text-[#0071e3]" />
        <div>
          <b className="text-sm">{eventDate}</b>
          <p className="text-xs text-[#86868b]">{eventTitle}</p>
        </div>
      </div>
    </motion.div>
  );
}

