// @ts-nocheck: setup() es JavaScript del DOM sin tipos, el mismo de la pestaña JS.
import { useEffect, useRef, type CSSProperties } from "react";

const css = `
.uv-ks {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  position: relative;
  width: 16em;
  padding: 1px;
  border-radius: 1.4em;
  font-size: var(--s);
  background: radial-gradient(12em circle at var(--x,50%) var(--y,0%),var(--c1),color-mix(in srgb,var(--fg) 12%,transparent) 60%);
}

.uv-ks>div {
  padding: 1.6em;
  border-radius: calc(1.4em - 1px);
  background: radial-gradient(14em circle at var(--x,50%) var(--y,0%),color-mix(in srgb,var(--c1) 10%,var(--bg)),var(--bg) 70%);
}

.uv-ks h3 {
  margin: 0 0 .4em;
  font-size: 1.2em;
  color: var(--fg);
}

.uv-ks p {
  margin: 0;
  font-size: .85em;
  line-height: 1.5;
  color: color-mix(in srgb,var(--fg) 60%,transparent);
}
`;

// Interacción en JavaScript del DOM: la misma que en la pestaña JS.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function setup(el: any) {
  el.addEventListener("pointermove",e=>{const r=el.getBoundingClientRect();el.style.setProperty("--x",e.clientX-r.left+"px");el.style.setProperty("--y",e.clientY-r.top+"px")})
}

export default function CardSpot() {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = ref.current?.firstElementChild;
    return el ? setup(el) : undefined;
  }, []);

  return (
    <>
      <style>{css}</style>
      <div
        ref={ref} style={{
          "--c1": "#0071e3",
          "--c2": "#8ec5ff",
          "--s": "16px",
          "--k": "1",
          "--fg": "#1d1d1f",
          "--bg": "#f5f5f7",
        } as CSSProperties}
      >
        <div className="uv-ks"><div><h3>Rendimiento</h3><p>Pasa el ratón por el borde y verás cómo la luz te persigue.</p></div></div>
      </div>
    </>
  );
}

