.uv-kf {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-kf {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  width: 14em;
  height: 17em;
  font-size: var(--s);
  perspective: 60em;
}

.uv-kf .in {
  position: relative;
  height: 100%;
  transform-style: preserve-3d;
  transition: transform calc(0.8s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-kf:hover .in {
  transform: rotateY(180deg);
}

.uv-kf .f,.uv-kf .b {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 1.5em;
  border-radius: 1.4em;
  backface-visibility: hidden;
}

.uv-kf .f {
  background: linear-gradient(160deg,var(--c2),var(--c1));
  color: #fff;
  box-shadow: 0 20px 40px -20px var(--c1);
}

.uv-kf .b {
  background: var(--bg);
  color: var(--fg);
  transform: rotateY(180deg);
  box-shadow: inset 0 0 0 1px color-mix(in srgb,var(--fg) 12%,transparent);
}

.uv-kf h3 {
  margin: 0;
  font-size: 1.3em;
}

.uv-kf p {
  margin: .3em 0 0;
  font-size: .85em;
  opacity: .7;
}

