  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-cplay {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  width: 16em;
  padding: 1.2em;
  border-radius: 1.5em;
  font-size: var(--s);
  color: var(--fg);
  background: var(--bg);
  box-shadow: inset 0 0 0 1px color-mix(in srgb,var(--fg) 8%,transparent),0 28px 70px -40px var(--c1);
  text-align: center;
}

.uv-cplay .cover {
  position: relative;
  height: 11em;
  border-radius: 1.1em;
  overflow: hidden;
  background: conic-gradient(from 30deg,var(--c1),var(--c2),color-mix(in srgb,var(--c1) 30%,#000),var(--c1));
}

.uv-cplay .cover i {
  position: absolute;
  inset: 16%;
  border-radius: 45% 55% 60% 40%;
  border: 1px solid rgba(255,255,255,.45);
  animation: uv-cplay-r calc(8s / var(--k)) linear infinite;
}

.uv-cplay .cover b {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: 3em;
  color: #fff;
}

.uv-cplay small {
  display: block;
  margin-top: 1.1em;
  font-size: .58em;
  color: var(--c1);
}

.uv-cplay h3 {
  margin: .25em 0;
  font-size: 1.12em;
}

.uv-cplay p {
  margin: 0;
  font-size: .75em;
  opacity: .5;
}

.uv-cplay .line {
  height: .25em;
  margin: 1em 0;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 10%,transparent);
}

.uv-cplay .line i {
  display: block;
  width: 42%;
  height: 100%;
  border-radius: inherit;
  background: var(--c1);
}

.uv-cplay footer {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 1em;
}

.uv-cplay button {
  width: 2.2em;
  height: 2.2em;
  border: 0;
  border-radius: 50%;
  font: inherit;
  color: var(--fg);
  background: transparent;
  cursor: pointer;
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-cplay .play {
  color: #fff;
  background: var(--c1);
}

.uv-cplay button:hover {
  transform: scale(1.14);
}

.uv-cplay button:active {
  transform: scale(.88);
}

@keyframes uv-cplay-r {
  to {
    transform: rotate(360deg);
  }
}

