.uv-cweather {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-cweather {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  position: relative;
  width: 17em;
  overflow: hidden;
  padding: 1.4em;
  border-radius: 1.5em;
  font-size: var(--s);
  color: #fff;
  background: linear-gradient(160deg,color-mix(in srgb,var(--c1) 75%,#15243a),color-mix(in srgb,var(--c2) 45%,#13202b));
  box-shadow: 0 25px 60px -30px var(--c1);
}

.uv-cweather .sky {
  position: absolute;
  inset: 0;
  overflow: hidden;
  opacity: .7;
}

.uv-cweather .sky i {
  position: absolute;
  right: -1em;
  top: 2em;
  width: 7em;
  height: 2em;
  border-radius: 999px;
  background: rgba(255,255,255,.25);
  filter: blur(4px);
  animation: uv-cw-cloud calc(8s / var(--k)) ease-in-out infinite alternate;
}

.uv-cweather .sky i+i {
  right: 5em;
  top: 4.2em;
  width: 5em;
  animation-direction: alternate-reverse;
}

.uv-cweather .sky b {
  position: absolute;
  left: calc(52% + var(--i)*6%);
  top: 6em;
  width: 1px;
  height: 1.2em;
  background: linear-gradient(transparent,rgba(255,255,255,.7));
  transform: rotate(12deg);
  animation: uv-cw-rain calc(0.9s / var(--k)) linear infinite;
  animation-delay: calc(var(--i)*-.11s);
}

.uv-cweather header,.uv-cweather>strong,.uv-cweather>p,.uv-cweather footer {
  position: relative;
}

.uv-cweather header {
  display: flex;
  justify-content: space-between;
}

.uv-cweather small {
  opacity: .6;
}

.uv-cweather>strong {
  display: block;
  margin: .45em 0 0;
  font-size: 4.4em;
  font-weight: 300;
}

.uv-cweather>p {
  margin: -.3em 0 1.5em;
  font-size: .75em;
  opacity: .7;
}

.uv-cweather footer {
  display: flex;
  border-top: 1px solid rgba(255,255,255,.18);
  padding-top: 1em;
}

.uv-cweather footer span {
  flex: 1;
  font-size: .65em;
  opacity: .65;
}

.uv-cweather footer b {
  display: block;
  margin-top: .35em;
  font-size: 1.35em;
  opacity: 1;
}

@keyframes uv-cw-cloud {
  to {
    transform: translateX(-2em);
  }
}

@keyframes uv-cw-rain {
  to {
    transform: translate(-.5em,4em) rotate(12deg);
    opacity: 0;
  }
}

