css:
.uv-ksd {
  --c1: #f43f5e;
  --c2: #10b981;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-ksd {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 15em;
  text-align: center;
}

.uv-ksd .ti {
  margin: 0 0 .8em;
  font-weight: 700;
}

.uv-ksd .dk {
  position: relative;
  height: 17em;
}

.uv-ksd article {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 1.1em;
  border-radius: 1.4em;
  text-align: left;
  color: #fff;
  background: linear-gradient(160deg,var(--g));
  box-shadow: 0 1em 2em -1.2em rgba(0,0,0,.55);
  transform-origin: 50% 120%;
  touch-action: none;
  user-select: none;
  cursor: grab;
  transition: transform calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1),opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-ksd article .ph {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(70% 50% at 70% 25%,rgba(255,255,255,.45),transparent 60%),linear-gradient(transparent 50%,rgba(0,0,0,.35));
  pointer-events: none;
}

.uv-ksd article b {
  position: relative;
  font-size: 1.5em;
  letter-spacing: -.02em;
}

.uv-ksd article span:not(.ph) {
  position: relative;
  font-size: .85em;
  opacity: .85;
}

.uv-ksd article i {
  position: absolute;
  top: 1em;
  padding: .25em .6em;
  border-radius: .4em;
  font-style: normal;
  font-weight: 800;
  font-size: .8em;
  border: 2px solid;
  opacity: 0;
  text-transform: none;
}

.uv-ksd .nope {
  right: 1em;
  color: #fff;
  transform: rotate(12deg);
  opacity: calc(var(--x,0) * -.02);
}

.uv-ksd .like {
  left: 1em;
  color: #fff;
  transform: rotate(-12deg);
  opacity: calc(var(--x,0) * .02);
}

.uv-ksd article:nth-last-child(2) {
  transform: scale(.95) translateY(.6em);
}

.uv-ksd article:nth-last-child(3) {
  transform: scale(.9) translateY(1.2em);
}

.uv-ksd article:nth-last-child(n+4) {
  transform: scale(.85) translateY(1.8em);
  opacity: 0;
}

.uv-ksd article.is-drag {
  transition: none;
  cursor: grabbing;
}

.uv-ksd .bt {
  display: flex;
  justify-content: center;
  gap: 1em;
  margin-top: 1.4em;
}

.uv-ksd .bt button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  width: 3em;
  height: 3em;
  border-radius: 50%;
  background: var(--bg);
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent),0 .6em 1.2em -.6em rgba(0,0,0,.4);
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-ksd .bt svg {
  width: 1.3em;
  height: 1.3em;
}

.uv-ksd .bt .no {
  color: var(--c1);
}

.uv-ksd .bt .ys {
  color: var(--c2);
}

.uv-ksd .bt button:hover {
  transform: scale(1.1);
}

.uv-ksd .bt button:active {
  transform: scale(.9);
}

.uv-ksd .bt button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

