document.querySelectorAll(".uv-ksd").forEach(el => {
  const dk=el.querySelector(".dk");let a=null,x0=0,dx=0,sc=1;const top=()=>dk.lastElementChild;
const fly=(dir)=>{const c=top();if(!c||c.dataset.out)return;c.dataset.out="1";c.style.transition="";c.style.transform="translate("+dir*140+"%,-10%) rotate("+dir*25+"deg)";c.style.opacity="0";
setTimeout(()=>{c.style.transition="none";c.style.transform="";c.style.opacity="";c.style.removeProperty("--x");delete c.dataset.out;dk.prepend(c);void c.offsetWidth;c.style.transition=""},420)};
dk.addEventListener("pointerdown",e=>{const c=top();if(!c||!c.contains(e.target))return;a=c;x0=e.clientX;sc=dk.getBoundingClientRect().width/dk.offsetWidth||1;a.setPointerCapture(e.pointerId);a.classList.add("is-drag")});
dk.addEventListener("pointermove",e=>{if(!a)return;dx=(e.clientX-x0)/sc;a.style.transform="translateX("+dx+"px) rotate("+dx/12+"deg)";a.style.setProperty("--x",dx.toFixed(0))});
const up=()=>{if(!a)return;const c=a;a=null;c.classList.remove("is-drag");if(Math.abs(dx)>90)fly(Math.sign(dx));else{c.style.transform="";c.style.removeProperty("--x")}dx=0};
dk.addEventListener("pointerup",up);dk.addEventListener("pointercancel",up);
el.querySelector(".no").addEventListener("click",()=>fly(-1));el.querySelector(".ys").addEventListener("click",()=>fly(1))
});

