css:
.uv-kst {
  --c1: #16a34a;
  --c2: #dcfce7;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-kst {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 17em;
  padding: 1.2em;
  border-radius: 1.5em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 8%,transparent),0 24px 48px -30px rgba(0,0,0,.45);
}

.uv-kst header {
  display: flex;
  align-items: center;
  gap: .7em;
}

.uv-kst .lg {
  display: grid;
  place-items: center;
  width: 2.4em;
  height: 2.4em;
  border-radius: .8em;
  font-weight: 800;
  font-size: .85em;
  color: #fff;
  background: linear-gradient(135deg,var(--c1),color-mix(in srgb,var(--c1) 50%,#0ea5e9));
}

.uv-kst h3 {
  margin: 0;
  font-size: .95em;
  font-weight: 700;
}

.uv-kst .tk {
  font-size: .72em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-kst .pr {
  display: flex;
  align-items: baseline;
  gap: .6em;
  margin: .9em 0 .4em;
}

.uv-kst .pr b {
  font-size: 1.6em;
  letter-spacing: -.02em;
  font-variant-numeric: tabular-nums;
}

.uv-kst .ch {
  padding: .2em .5em;
  border-radius: .5em;
  font-size: .75em;
  font-weight: 700;
  color: var(--c1);
  background: var(--c2);
}

.uv-kst .gr {
  position: relative;
  height: 6.5em;
  color: var(--c1);
  cursor: crosshair;
}

.uv-kst svg {
  width: 100%;
  height: 100%;
  overflow: visible;
}

.uv-kst .ar {
  fill: url(#uv-kst-g);
  transition: opacity calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-kst .ln {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  vector-effect: non-scaling-stroke;
  stroke-linejoin: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: uv-kst calc(1.4s / var(--k)) cubic-bezier(.22,1,.36,1) forwards;
}

.uv-kst .cx {
  stroke: color-mix(in srgb,var(--fg) 35%,transparent);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
  stroke-dasharray: 3 3;
  opacity: 0;
}

.uv-kst .tp {
  position: absolute;
  top: -.4em;
  left: 0;
  padding: .25em .5em;
  border-radius: .4em;
  font-size: .72em;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: #fff;
  background: var(--fg);
  transform: translateX(-50%);
  opacity: 0;
  pointer-events: none;
  transition: opacity calc(0.15s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-kst .gr.on .cx,.uv-kst .gr.on .tp {
  opacity: 1;
}

.uv-kst .pe {
  display: flex;
  gap: .3em;
  margin-top: .8em;
}

.uv-kst .pe label {
  position: relative;
  cursor: pointer;
}

.uv-kst .pe input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}

.uv-kst .pe span {
  display: block;
  padding: .35em .8em;
  border-radius: .6em;
  font-size: .78em;
  font-weight: 700;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  transition: all calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-kst .pe input:checked + span {
  color: var(--fg);
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uv-kst .pe input:focus-visible + span {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

@keyframes uv-kst {
  to {
    stroke-dashoffset: 0;
  }
}

