.uv-kpg {
  --c1: #ff385c;
  --c2: #ffe4ea;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-kpg {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 16em;
}

.uv-kpg .ph {
  position: relative;
  height: 11em;
  border-radius: 1.2em;
  overflow: hidden;
  outline: 0;
}

.uv-kpg .ph:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-kpg .ph>i {
  position: absolute;
  inset: 0;
  opacity: 0;
  transform: scale(1.04);
  transition: opacity calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.8s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-kpg .ph>i.on {
  opacity: 1;
  transform: none;
}

.uv-kpg .dots {
  position: absolute;
  left: 50%;
  bottom: .7em;
  display: flex;
  gap: .3em;
  translate: -50% 0;
}

.uv-kpg .dots b {
  width: .4em;
  height: .4em;
  border-radius: 1em;
  background: rgba(255,255,255,.6);
  transition: all calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-kpg .dots b.on {
  width: 1.1em;
  background: #fff;
}

.uv-kpg .sv {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  right: .6em;
  top: .6em;
  display: grid;
  place-items: center;
  width: 2.2em;
  height: 2.2em;
  border-radius: 50%;
  color: #fff;
  background: rgba(0,0,0,.25);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  transition: transform calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-kpg .sv svg {
  width: 1.15em;
  height: 1.15em;
  transition: fill calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-kpg .sv[aria-pressed="true"] {
  color: var(--c1);
  background: #fff;
}

.uv-kpg .sv[aria-pressed="true"] svg {
  fill: var(--c1);
}

.uv-kpg .sv.pop {
  animation: uv-kpg calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-kpg .sv:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-kpg .bg {
  position: absolute;
  left: .6em;
  top: .6em;
  padding: .3em .6em;
  border-radius: .5em;
  font-size: .7em;
  font-weight: 700;
  background: #fff;
  color: #111;
}

.uv-kpg .tx {
  padding: .8em .2em 0;
}

.uv-kpg h3 {
  margin: 0;
  font-size: 1em;
  letter-spacing: -.01em;
  font-weight: 700;
}

