}

.uv-kpg .mt span {
  display: inline-flex;
  align-items: center;
  gap: .3em;
}

.uv-kpg .mt svg {
  width: 1.15em;
  height: 1.15em;
}

.uv-kpg .pr {
  margin: 0;
}

.uv-kpg .pr b {
  font-variant-numeric: tabular-nums;
}

.uv-kpg .pr span {
  font-size: .85em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

@keyframes uv-kpg {
  40% {
    transform: scale(1.3);
  }
}

