  -webkit-tap-highlight-color: transparent;
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: grid;
  justify-items: center;
  gap: 1.1em;
  width: 15em;
  text-align: center;
}

.uvq07-pol .fr {
  display: block;
  width: 13em;
  padding: .75em .75em 0;
  border-radius: .15em;
