  aspect-ratio: 1;
  overflow: hidden;
  filter: saturate(.15) sepia(.5) contrast(.8);
  transition: filter calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq07-pol .ph i {
  position: absolute;
