  right: 0;
  top: 60%;
  bottom: 16%;
  background: repeating-linear-gradient(180deg,rgba(255,255,255,.16) 0 1px,transparent 1px 6px),linear-gradient(180deg,color-mix(in srgb,var(--c2) 70%,var(--c1)),var(--c2));
}

.uvq07-pol .se::after {
  content: "";
  position: absolute;
  left: 41%;
  width: 18%;
  top: 0;
  bottom: 0;
  background: repeating-linear-gradient(180deg,#ffe2a8 0 2px,transparent 2px 6px);
