  mask: linear-gradient(#000,transparent);
}

.uvq07-pol .sa {
  left: 0;
  right: 0;
  bottom: 0;
  height: 16%;
  background: linear-gradient(180deg,#ecd3a5,#d6b07a);
}

.uvq07-pol .dv {
  inset: 0;
  background: radial-gradient(circle at 45% 40%,#4a463d,#1c1b18 75%);
  transition: opacity calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq07-pol[aria-pressed="true"] .ph {
  filter: none;
  transition-duration: calc(3s / var(--k));
}

.uvq07-pol[aria-pressed="true"] .dv {
  opacity: 0;
  transition-duration: calc(3.2s / var(--k));
}

.uvq07-pol .cp {
  display: block;
  padding: .6em .2em .85em;
  font-family: "Segoe Print","Bradley Hand","Marker Felt","Comic Sans MS",cursive;
