}

.uvq07-pol .h2,.uvq07-pol[aria-pressed="true"] .h1 {
  opacity: 0;
}

.uvq07-pol[aria-pressed="true"] .h2 {
  opacity: 1;
}

.uvq07-pol.shk .fr {
  animation: uvq07-pol calc(0.7s / var(--k)) ease-in-out;
}

@keyframes uvq07-pol {
  20% {
    transform: rotate(4deg) translateX(.5em);
  }
  40% {
    transform: rotate(-7deg) translateX(-.5em);
  }
