.uvq07-vnl {
  --c1: #e8622c;
  --c2: #1f6f6b;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq07-vnl {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 17em;
  padding: 1em;
  border-radius: 1.5em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 8%,transparent),0 24px 48px -30px rgba(0,0,0,.45);
}

.uvq07-vnl .st {
  position: relative;
  height: 10em;
}

.uvq07-vnl .slv {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 1;
  width: 10em;
  height: 10em;
  overflow: hidden;
  border-radius: .25em;
  background: #f1e4cb;
  box-shadow: .3em .5em 1.2em -.4em rgba(0,0,0,.45),inset 0 0 0 1px rgba(0,0,0,.06);
}

.uvq07-vnl .slv i {
  position: absolute;
  inset: 0;
}

.uvq07-vnl .sun {
  background: radial-gradient(circle at 50% 118%,var(--c2) 0 20%,#f1e4cb 20% 24%,#f4b942 24% 37%,#f1e4cb 37% 41%,var(--c1) 41% 54%,#f1e4cb 54% 58%,color-mix(in srgb,var(--c1) 55%,#5a1e10) 58% 71%,transparent 71%);
}

.uvq07-vnl .slv b {
  position: absolute;
  left: .55em;
  top: .4em;
  font: 800 1.6em/1 "Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
  letter-spacing: -.05em;
  color: #2b1a12;
}

.uvq07-vnl .slv small {
  position: absolute;
  right: .8em;
  top: .9em;
  font-size: .55em;
  font-weight: 800;
  letter-spacing: .25em;
  color: #2b1a12;
}

.uvq07-vnl .rec {
  position: absolute;
  left: .4em;
  top: .4em;
  width: 9.2em;
  height: 9.2em;
  border-radius: 50%;
  background: repeating-radial-gradient(circle,#141414 0 1px,#202020 1px 2.5px);
  box-shadow: 0 .4em 1em -.4em rgba(0,0,0,.6);
  transform: translateX(2em) rotate(20deg);
  transition: transform calc(0.7s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq07-vnl .rec::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: conic-gradient(from 20deg,transparent,rgba(255,255,255,.15) 8%,transparent 16% 50%,rgba(255,255,255,.1) 58%,transparent 66%);
}

.uvq07-vnl .rec i {
  position: absolute;
  inset: 32%;
  border-radius: 50%;
  background: radial-gradient(circle,#111 0 7%,transparent 8%),linear-gradient(transparent 44%,rgba(255,255,255,.55) 44% 52%,transparent 52%),var(--c1);
}

.uvq07-vnl:hover .rec,.uvq07-vnl:focus-within .rec {
  transform: translateX(4.4em) rotate(50deg);
}

.uvq07-vnl.on .rec {
  transform: translateX(4.8em) rotate(0);
}

.uvq07-vnl.on .rec i {
  animation: uvq07-vnl calc(1.8s / var(--k)) linear infinite;
}

.uvq07-vnl .tx {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .8em;
  margin-top: 1em;
}

.uvq07-vnl h3 {
  margin: 0;
  font-size: 1.05em;
  font-weight: 750;
  letter-spacing: -.01em;
}

.uvq07-vnl .tx p {
  display: flex;
  align-items: center;
  gap: .5em;
  margin: .25em 0 0;
  font-size: .78em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq07-vnl .eq {
  display: none;
  align-items: flex-end;
  gap: 2px;
  height: .9em;
}

.uvq07-vnl.on .eq {
  display: inline-flex;
}

.uvq07-vnl .eq i {
  width: 3px;
  height: 30%;
  border-radius: 1px;
  background: var(--c1);
  animation: uvq07-vnl-eq calc(0.7s / var(--k)) ease-in-out infinite alternate;
}

.uvq07-vnl .eq i:nth-child(2) {
  animation-delay: -.3s;
}

.uvq07-vnl .eq i:nth-child(3) {
  animation-delay: -.55s;
}

.uvq07-vnl button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  flex: none;
  display: grid;
  place-items: center;
  width: 2.8em;
  height: 2.8em;
  border-radius: 50%;
  color: #fff;
  background: var(--c1);
  box-shadow: 0 .5em 1em -.5em var(--c1);
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq07-vnl button svg {
  width: 1.2em;
  height: 1.2em;
}

.uvq07-vnl button .pa,.uvq07-vnl button[aria-pressed="true"] .py {
  display: none;
}

.uvq07-vnl button[aria-pressed="true"] .pa {
  display: block;
}

.uvq07-vnl button:hover {
  transform: scale(1.08);
}

.uvq07-vnl button:active {
  transform: scale(.92);
}

.uvq07-vnl button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

@keyframes uvq07-vnl {
  to {
    transform: rotate(360deg);
  }
}

@keyframes uvq07-vnl-eq {
  to {
    height: 100%;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq07-vnl,.uvq07-vnl *,.uvq07-vnl *::before,.uvq07-vnl *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

