css:
.uvq07-plt {
  --c1: #c4643f;
  --c2: #3f8f5a;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq07-plt {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 16em;
  padding: 1em;
  border-radius: 1.5em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 8%,transparent),0 24px 48px -30px rgba(0,0,0,.45);
}

.uvq07-plt .stg {
  position: relative;
  display: grid;
  place-items: end center;
  height: 10.5em;
  overflow: hidden;
  border-radius: 1em;
  background: radial-gradient(80% 70% at 50% 35%,color-mix(in srgb,var(--c2) 16%,transparent),transparent 70%),color-mix(in srgb,var(--fg) 4%,transparent);
}

.uvq07-plt .stg>svg {
  width: 9em;
  height: 9.75em;
}

.uvq07-plt .g1 {
  stop-color: color-mix(in srgb,var(--c1) 75%,#000);
}

.uvq07-plt .g2 {
  stop-color: color-mix(in srgb,var(--c1) 85%,#fff);
}

.uvq07-plt .pb {
  fill: url(#uvq07-plt-g);
}

.uvq07-plt .rm {
  fill: color-mix(in srgb,var(--c1) 88%,#fff);
}

.uvq07-plt .so {
  fill: #4a3426;
}

.uvq07-plt .lf {
  transform: rotate(calc(var(--r) * 2 + 8deg)) scale(.9,.84);
  transition: transform calc(1.1s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq07-plt.ok .lf {
  transform: rotate(var(--r));
}

.uvq07-plt .sm {
  fill: none;
  stroke: color-mix(in srgb,var(--c2) 70%,#6b5a2a);
  stroke-width: 2.2;
  stroke-linecap: round;
}

.uvq07-plt .lp {
  fill: color-mix(in srgb,var(--c2) 35%,#b39a48);
  transition: fill calc(1s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq07-plt.ok .lp {
  fill: var(--c2);
}

.uvq07-plt .vn {
  fill: none;
  stroke: rgba(255,255,255,.35);
  stroke-width: 1;
}

.uvq07-plt .dp {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.uvq07-plt .dp i {
  position: absolute;
  top: 2.2em;
  left: calc(51% + var(--i) * .38em);
  width: .3em;
  height: .42em;
  border-radius: 50% 50% 50% 50%/60% 60% 40% 40%;
  background: #5ab4e5;
  opacity: 0;
}

.uvq07-plt.wt .dp i {
  animation: uvq07-plt calc(0.7s / var(--k)) ease-in 3 both;
  animation-delay: calc(var(--i) * calc(0.11s / var(--k)));
}

.uvq07-plt .can {
  position: absolute;
  right: 1em;
  top: .7em;
  width: 2.7em;
  color: #64748b;
  transform-origin: 30% 70%;
  transition: transform calc(0.45s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq07-plt .can svg {
  display: block;
  width: 100%;
}

.uvq07-plt.wt .can {
  transform: rotate(-26deg) translateX(-.2em);
}

.uvq07-plt h3 {
  margin: .9em 0 0;
  font-size: 1em;
  font-weight: 700;
}

.uvq07-plt .mt {
  display: grid;
