  gap: .35em;
  margin: .6em 0 .35em;
  font-size: .78em;
}

.uvq07-plt .mt span {
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq07-plt .mt b {
  font-variant-numeric: tabular-nums;
}

.uvq07-plt .mt i {
  grid-column: 1/-1;
