  background: color-mix(in srgb,var(--fg) 6%,transparent);
  overflow: hidden;
}

.uvq07-plt .mt i::after {
  content: "";
  display: block;
  height: 100%;
  width: var(--m,22%);
  border-radius: inherit;
  background: linear-gradient(90deg,#5ab4e5,color-mix(in srgb,#5ab4e5 40%,var(--c2)));
  transition: width calc(1.2s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq07-plt .st {
  margin: 0;
  font-size: .78em;
  font-weight: 700;
  color: var(--c1);
}

.uvq07-plt.ok .st {
  color: var(--c2);
}

.uvq07-plt .bs {
  display: flex;
  gap: .5em;
  margin-top: .9em;
}

.uvq07-plt .bs button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: .65em .8em;
  border-radius: .8em;
  font-size: .82em;
  font-weight: 700;
  transition: transform calc(0.25s / var(--k)) cubic-bezier(.34,1.56,.64,1),background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq07-plt .bs .wa {
  flex: 1;
  color: #fff;
  background: var(--c2);
}

.uvq07-plt .bs .wk {
  background: color-mix(in srgb,var(--fg) 6%,transparent);
