.uvq07-clk {
  --c1: #d4a72c;
  --c2: #1a2a44;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq07-clk {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 18.5em;
  box-sizing: border-box;
  padding: 1.2em;
  border-radius: 1.5em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 8%,transparent),0 24px 48px -30px rgba(0,0,0,.45);
}

.uvq07-clk h3 {
  margin: 0;
  font-size: 1em;
  font-weight: 750;
}

.uvq07-clk header p {
  margin: .2em 0 0;
  font-size: .74em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq07-clk ul {
  list-style: none;
  margin: 1.1em 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: .5em;
}

.uvq07-clk li {
  display: grid;
  justify-items: center;
  gap: .12em;
  text-align: center;
}

.uvq07-clk .dl {
  position: relative;
  width: 4.9em;
  height: 4.9em;
  margin-bottom: .5em;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 35%,#fffdf7,#ece5d6);
  box-shadow: 0 0 0 .22em color-mix(in srgb,var(--c1) 65%,#7a6a45),0 .7em 1.2em -.6em rgba(0,0,0,.45),inset 0 .15em .3em rgba(0,0,0,.12);
  transition: background calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq07-clk li:hover .dl {
  transform: translateY(-.2em) scale(1.04);
}

.uvq07-clk .dl i {
  position: absolute;
  left: 50%;
  top: .3em;
  width: .12em;
  height: .42em;
  margin-left: -.06em;
  background: var(--c2);
  transform-origin: 50% 2.15em;
  transform: rotate(calc(var(--i) * 30deg));
}

.uvq07-clk .dl i:nth-child(3n+1) {
  width: .2em;
  height: .62em;
  margin-left: -.1em;
}

