  position: absolute;
  left: 50%;
  bottom: 50%;
  border-radius: 1em;
  transform-origin: 50% 100%;
}

.uvq07-clk .h {
  width: .22em;
  height: 1.25em;
  margin-left: -.11em;
  background: var(--c2);
}

.uvq07-clk .m {
  width: .15em;
  height: 1.85em;
  margin-left: -.075em;
  background: var(--c2);
}

