.uvq07-map {
  --c1: #d2452f;
  --c2: #3c7fa8;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq07-map {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: grid;
  justify-items: center;
  gap: 1.4em;
  width: 20em;
}

.uvq07-map .mp {
  position: relative;
  width: 19.5em;
  height: 10em;
  perspective: 60em;
}

.uvq07-map .mp::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -.9em;
  width: var(--sw,7.5em);
  height: 1em;
  translate: -50% 0;
  border-radius: 50%;
  background: radial-gradient(closest-side,rgba(0,0,0,.3),transparent);
  transition: width calc(0.9s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq07-map.open .mp {
  --sw: 19em;
}

.uvq07-map .p1 {
  position: absolute;
  left: 0;
  top: 0;
  width: 6.5em;
  height: 10em;
  transform-style: preserve-3d;
  transform: translateX(6.5em);
  transition: transform calc(0.9s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq07-map.open .p1 {
  transform: none;
}

.uvq07-map .p2,.uvq07-map .p3 {
  position: absolute;
  left: 100%;
  top: 0;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  transform-origin: 0 50%;
  transition: transform calc(0.9s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq07-map .p2 {
  transform: rotateY(-178deg);
  transition-delay: calc(0.18s / var(--k));
}

.uvq07-map .p3 {
  transform: rotateY(-176deg);
}

.uvq07-map.open .p2 {
  transform: none;
  transition-delay: 0s;
}

.uvq07-map.open .p3 {
  transform: none;
  transition-delay: calc(0.18s / var(--k));
}

.uvq07-map .fc {
  position: absolute;
  inset: 0;
  overflow: hidden;
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
  background: #f6f1e3;
}

.uvq07-map .bk {
  transform: rotateY(180deg);
}

.uvq07-map .art {
  position: absolute;
  top: 0;
  left: calc(var(--o) * -6.5em);
  width: 19.5em;
  height: 10em;
}

.uvq07-map .art svg {
  display: block;
  width: 100%;
  height: 100%;
}

.uvq07-map .p1>.fr {
  border-radius: .3em 0 0 .3em;
  box-shadow: inset -.7em 0 .8em -.7em rgba(0,0,0,.2);
}

.uvq07-map .p2>.fr {
  box-shadow: inset .7em 0 .8em -.7em rgba(255,255,255,.7),inset -.7em 0 .8em -.7em rgba(0,0,0,.2);
