.uvq07-lck {
  --c1: #22c58b;
  --c2: #1d2126;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq07-lck {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 16em;
  padding: 1.2em;
  border-radius: 1.6em;
  text-align: center;
  color: #eef1f4;
  background: radial-gradient(90% 60% at 50% 0%,rgba(255,255,255,.07),transparent 70%),var(--c2);
  box-shadow: 0 1.4em 2.4em -1.2em rgba(0,0,0,.7),inset 0 1px 0 rgba(255,255,255,.08),0 0 0 1px color-mix(in srgb,var(--fg) 8%,transparent);
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
}

.uvq07-lck header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  text-align: left;
}

.uvq07-lck h3 {
  margin: 0;
  font-size: .98em;
  font-weight: 700;
}

.uvq07-lck .st {
  display: flex;
  align-items: center;
  gap: .4em;
  margin: .25em 0 0;
  font-size: .76em;
  color: rgba(238,241,244,.65);
}

.uvq07-lck .st i {
  width: .5em;
  height: .5em;
  border-radius: 50%;
  background: #f59e0b;
  box-shadow: 0 0 .5em #f59e0b;
}

.uvq07-lck.op .st i {
  background: var(--c1);
  box-shadow: 0 0 .5em var(--c1);
}

.uvq07-lck .bt {
  display: inline-flex;
  align-items: center;
  gap: .3em;
  font-size: .72em;
  color: rgba(238,241,244,.6);
}

.uvq07-lck .bt svg {
  width: 1.4em;
  height: 1.4em;
}

.uvq07-lck .hb {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: grid;
  place-items: center;
  width: 7.2em;
  height: 7.2em;
  margin: 1.3em auto .9em;
  border-radius: 50%;
  touch-action: none;
  color: #eef1f4;
  background: radial-gradient(circle at 50% 35%,rgba(255,255,255,.1),rgba(255,255,255,.02) 70%);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.08);
  transition: transform calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq07-lck .hb:hover {
  background: radial-gradient(circle at 50% 35%,rgba(255,255,255,.14),rgba(255,255,255,.03) 70%);
}

.uvq07-lck.hd .hb {
  transform: scale(.95);
}

.uvq07-lck .hb:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq07-lck .rg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.uvq07-lck .rg circle {
  fill: none;
  stroke-width: 4;
}

.uvq07-lck .tr {
  stroke: rgba(255,255,255,.08);
}

.uvq07-lck .pr {
  stroke: var(--c1);
  stroke-linecap: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  transition: stroke-dashoffset calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

