.uvq07-nut {
  --c1: #141414;
  --c2: #ffd23f;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq07-nut {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 16em;
  padding: 1em 1.1em 1.1em;
  border-radius: .5em;
  font-family: "Helvetica Neue",Helvetica,Arial,sans-serif;
  color: var(--c1);
  background: #fffefb;
  box-shadow: 0 0 0 1px rgba(0,0,0,.08),0 1.2em 2em -1.2em rgba(0,0,0,.5);
}

.uvq07-nut h3 {
  margin: 0;
  padding-right: 2.6em;
  font-size: 1.45em;
  font-weight: 900;
  font-stretch: condensed;
  letter-spacing: -.03em;
  line-height: 1;
}

.uvq07-nut .pd {
  margin: .35em 0 .5em;
  font-size: .78em;
}

.uvq07-nut .sv {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: .45em 0;
  border-top: .5em solid var(--c1);
  border-bottom: 1px solid var(--c1);
  font-size: .8em;
  font-weight: 700;
}

.uvq07-nut .stp {
  display: flex;
  align-items: center;
  gap: .2em;
}

.uvq07-nut .stp button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  width: 1.9em;
  height: 1.9em;
  border-radius: 50%;
  font-weight: 800;
  line-height: 1;
  border: 1.5px solid var(--c1);
  transition: transform calc(0.2s / var(--k)) cubic-bezier(.34,1.56,.64,1),background calc(0.15s / var(--k)) cubic-bezier(.25,.1,.25,1),color calc(0.15s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq07-nut .stp button:hover:not(:disabled) {
  color: #fffefb;
  background: var(--c1);
}

.uvq07-nut .stp button:active:not(:disabled) {
  transform: scale(.86);
}

.uvq07-nut .stp button:disabled {
  opacity: .3;
  cursor: default;
}

.uvq07-nut .stp button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 2px;
}

.uvq07-nut output {
  min-width: 1.6em;
  text-align: center;
  font-size: 1.3em;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
}

.uvq07-nut table {
  width: 100%;
  border-collapse: collapse;
  font-size: .74em;
}

.uvq07-nut thead th {
  padding: .35em 0;
  font-size: .85em;
  font-weight: 700;
  text-align: right;
  border-bottom: .25em solid var(--c1);
}

.uvq07-nut thead th:first-child {
  text-align: left;
}

.uvq07-nut tr {
  border-bottom: 1px solid color-mix(in srgb,var(--c1) 35%,transparent);
}

.uvq07-nut tbody th {
  padding: .3em 0;
  text-align: left;
  font-weight: 800;
}

.uvq07-nut tr.sb th {
  padding-left: 1em;
  font-weight: 400;
}

.uvq07-nut td {
  padding: .3em 0 .3em .6em;
  text-align: right;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.uvq07-nut td b {
  font-weight: 800;
}

.uvq07-nut tbody tr:last-child {
  border-bottom: .5em solid var(--c1);
}

.uvq07-nut .ft {
  margin: .6em 0 0;
  font-size: .58em;
  line-height: 1.35;
  opacity: .8;
}

.uvq07-nut .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.uvq07-nut .bd {
  position: absolute;
  right: -.7em;
  top: -.9em;
  display: grid;
  place-items: center;
  width: 4.6em;
  height: 4.6em;
  box-sizing: border-box;
  padding: .5em;
  border-radius: 50%;
  text-align: center;
  font-size: .66em;
  font-weight: 900;
  line-height: 1.05;
  text-transform: uppercase;
  color: #1a1a1a;
  background: var(--c2);
  transform: rotate(12deg);
  box-shadow: 0 .3em .6em -.2em rgba(0,0,0,.35),inset 0 0 0 .25em rgba(255,255,255,.35);
  transition: transform calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq07-nut:hover .bd {
  transform: rotate(4deg) scale(1.06);
}

@media (prefers-reduced-motion:reduce) {
  .uvq07-nut,.uvq07-nut *,.uvq07-nut *::before,.uvq07-nut *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

