document.querySelectorAll(".uvq07-nut").forEach(el => {
  const o=el.querySelector("output"),mn=el.querySelector(".mn"),pl=el.querySelector(".pl"),vs=[...el.querySelectorAll("b[data-v]")],irs=[...el.querySelectorAll("td[data-ir]")],sp=parseFloat(getComputedStyle(el).getPropertyValue("--k"))||1;let n=1,raf=0;
const fmt=(v,d)=>v.toFixed(d).replace(".",",");
const set=m=>{const from=n;n=Math.max(1,Math.min(6,m));if(n===from)return;o.textContent=String(n);mn.disabled=n===1;pl.disabled=n===6;cancelAnimationFrame(raf);const t0=performance.now(),D=450/sp;
const f=now=>{const p=Math.min(1,(now-t0)/D),e=1-Math.pow(1-p,3),q=from+(n-from)*e;vs.forEach(b=>{b.textContent=fmt(+b.dataset.v*q,+b.dataset.d)});irs.forEach(t=>{const ir=+t.dataset.ir;if(ir>0)t.textContent=Math.round(ir*q)+" %"});if(p<1)raf=requestAnimationFrame(f)};raf=requestAnimationFrame(f)};
mn.addEventListener("click",()=>set(n-1));pl.addEventListener("click",()=>set(n+1));return()=>cancelAnimationFrame(raf)
});

