.uvq07-pan {
  --c1: #c2562f;
  --c2: #2f5d63;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq07-pan {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: grid;
  justify-items: center;
  width: 20em;
}

.uvq07-pan .ti {
  margin: 0 0 .4em;
  font-size: .72em;
  font-weight: 800;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq07-pan .fn {
  position: relative;
  width: 20em;
  height: 14.6em;
  --a: 7deg;
}

.uvq07-pan .fn:hover,.uvq07-pan .fn:focus-within {
  --a: 15deg;
}

.uvq07-pan .fn button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  left: 50%;
  bottom: .4em;
  width: 3.5em;
  height: 13em;
  margin-left: -1.75em;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: .45em;
  text-align: left;
  background: #fbfaf7;
  box-shadow: 0 0 0 1px rgba(0,0,0,.08),0 .4em 1em -.4em rgba(0,0,0,.35);
  transform-origin: 50% calc(100% - 1.3em);
  transform: rotate(calc((var(--i) - 3) * var(--a))) translateY(var(--y,0em));
  transition: transform calc(0.6s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq07-pan .fn button:hover {
  --y: -.5em;
}

.uvq07-pan .fn button[aria-pressed="true"] {
  --y: -1.5em;
  z-index: 10;
}

.uvq07-pan .fn button:active {
  --y: -.2em;
}

.uvq07-pan .fn button:focus-visible {
  outline: 2px solid var(--fg);
  outline-offset: 2px;
}

.uvq07-pan .cl {
  flex: none;
  height: 62%;
  background: var(--sw);
  box-shadow: inset 0 -1px 0 rgba(0,0,0,.08);
}

.uvq07-pan .lb {
  display: grid;
  gap: .2em;
  padding: .5em .4em;
  color: #222;
}

.uvq07-pan .lb b {
  font: 700 .56em ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  white-space: nowrap;
}

.uvq07-pan .lb span {
  font-size: .6em;
  font-weight: 600;
  white-space: nowrap;
}

.uvq07-pan .rv {
  position: absolute;
  left: 50%;
  bottom: 1.7em;
  z-index: 20;
  width: .9em;
  height: .9em;
  margin: 0 0 -.45em -.45em;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%,#f5f5f5,#9a9a9a 60%,#5b5b5b);
  box-shadow: 0 .1em .2em rgba(0,0,0,.4);
}

.uvq07-pan .st {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: .6em;
  min-height: 1.8em;
  margin: .6em 0 0;
  font-size: .8em;
}

.uvq07-pan .nm {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.uvq07-pan .ok {
  padding: .2em .55em;
  border-radius: 1em;
  font-size: .85em;
  font-weight: 700;
  color: var(--bg);
  background: var(--fg);
  opacity: 0;
  transform: translateY(.3em);
  transition: opacity calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq07-pan.cp .ok {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion:reduce) {
  .uvq07-pan,.uvq07-pan *,.uvq07-pan *::before,.uvq07-pan *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

